//! Every icon of the IDE, embedded in the binary (table generated by `build.rs`).
//!
//! An icon may come in up to three files: `name.svg` for every theme, `name.dark.svg` and
//! `name.light.svg` for one theme only. Asking for an icon in a theme takes the file of that
//! theme, else the plain one, else the file of the other theme.

use eframe::egui::{ImageSource, load::Bytes};
use std::{
    borrow::Cow,
    collections::HashMap,
    hash::{DefaultHasher, Hash, Hasher},
    sync::{LazyLock, RwLock},
};

pub struct Variant {
    pub uri: &'static str,
    pub bytes: &'static [u8],
}

pub struct Icon {
    /// Where the icon lives, e.g. `ui` icons are `branch`, plugin ones `git/icons/branch`,
    /// file types `file/rust`.
    pub key: &'static str,
    /// Plain, light, dark.
    pub variants: [Option<Variant>; 3],
}

include!(concat!(env!("OUT_DIR"), "/icon_set.rs"));

impl Icon {
    pub fn variant(&self, dark: bool) -> Option<&Variant> {
        let order = if dark { [2, 0, 1] } else { [1, 0, 2] };
        order.iter().find_map(|&i| self.variants[i].as_ref())
    }
}

/// An icon by its key, or by its short name (`branch` for `git/icons/branch`), or one a native
/// plugin brought ([`register`]).
pub fn find(name: &str) -> Option<&'static Icon> {
    let by_key = |key: &str| {
        ICONS
            .binary_search_by(|icon| icon.key.cmp(key))
            .ok()
            .map(|i| &ICONS[i])
    };
    by_key(name)
        .or_else(|| {
            let index = SHORT_NAMES
                .binary_search_by(|(short, _)| short.cmp(&name))
                .ok()?;
            by_key(SHORT_NAMES[index].1)
        })
        .or_else(|| REGISTERED.read().ok()?.get(name).copied())
}

/// The icons of the native plugins, by key. They stay for the life of the IDE (a few
/// kilobytes each): what was drawn with them may be drawn again.
static REGISTERED: LazyLock<RwLock<HashMap<String, &'static Icon>>> =
    LazyLock::new(Default::default);

/// Adds an icon of a native plugin under `key` (`plugin:database/table`), as an SVG for every
/// theme, or one for the light themes and one for the dark ones. Registering the same key
/// again with the same pictures keeps the first.
pub fn register(key: &str, svg: &[u8], svg_dark: Option<&[u8]>) -> &'static str {
    let mut hasher = DefaultHasher::new();
    (svg, svg_dark).hash(&mut hasher);
    let hash = hasher.finish();
    let mut registered = REGISTERED.write().expect("icons");
    if let Some(icon) = registered.get(key)
        && icon.variants[0]
            .as_ref()
            .or(icon.variants[1].as_ref())
            .is_some_and(|v| v.uri.contains(&format!("{hash:016x}")))
    {
        return icon.key;
    }
    let leak = |bytes: &[u8]| -> &'static [u8] { Box::leak(bytes.to_vec().into_boxed_slice()) };
    let variant = |bytes: &[u8], theme: &str| Variant {
        uri: Box::leak(format!("bytes://plugin/{key}.{hash:016x}.{theme}.svg").into_boxed_str()),
        bytes: leak(bytes),
    };
    let key: &'static str = Box::leak(key.to_string().into_boxed_str());
    let variants = match svg_dark {
        Some(dark) => [
            None,
            Some(variant(svg, "light")),
            Some(variant(dark, "dark")),
        ],
        None => [Some(variant(svg, "all")), None, None],
    };
    let icon: &'static Icon = Box::leak(Box::new(Icon { key, variants }));
    registered.insert(key.to_string(), icon);
    key
}

/// The key of the icon of a built-in plugin, by the name of its folder (`cargo`, `github`): the
/// `icon` of the front matter of its documentation (`doc/en-US.md`), else its `icon.svg`. The
/// catalog of the documentation shows the same one.
pub fn plugin_icon(plugin: &str) -> Option<&'static str> {
    PLUGIN_ICONS
        .binary_search_by(|(p, _)| (*p).cmp(plugin))
        .ok()
        .map(|i| PLUGIN_ICONS[i].1)
}

pub fn source(name: &str, dark: bool) -> Option<ImageSource<'static>> {
    let variant = find(name)?.variant(dark)?;
    Some(ImageSource::Bytes {
        uri: Cow::Borrowed(variant.uri),
        bytes: Bytes::Static(variant.bytes),
    })
}

/// Key of the icon that an `extensions` file of `owner` (a plugin folder, or `file` for
/// languages and assets) gives to `path`: by file name first, then by extension, then by the
/// part of the name before its first dot (`Dockerfile.dev`).
pub fn extension_icon(owner: &str, path: &std::path::Path) -> Option<&'static str> {
    let name = path.file_name()?.to_str()?.to_ascii_lowercase();
    let extension = name.rsplit_once('.').map(|(_, e)| e);
    let first = name.split('.').next().filter(|f| !f.is_empty());
    [Some(name.as_str()), extension, first]
        .into_iter()
        .flatten()
        .find_map(|token| {
            let index = EXTENSIONS
                .binary_search_by(|(d, e, _)| (*d, *e).cmp(&(owner, token)))
                .ok()?;
            Some(EXTENSIONS[index].2)
        })
}
